-- Demo data for «برنامه‌ریزی و کنترل زمان» — پروژهٔ خط انتقال گاز ۴۸ اینچ کوهدشت–سرخس.
-- Generated by gen-demo.mjs (do not edit the data blocks by hand): Rev0 = approved baseline, Rev1/Rev2 = approved monthly updates (Rev2 is current), Rev3 = draft scenario.
-- Everything here is DEMONSTRATION data (invented progress, delays and probabilities). It refuses to run when the project already has a schedule.
-- copy of a version's calendars, activities (same uids) and relations into a draft version
create or replace function pg_temp.sch_copy(src uuid, dst uuid) returns void language plpgsql as $f$
begin
  insert into sch_calendars (project_id, version_id, code, name, work_days, hours_per_day, holidays, is_default, source_id)
    select project_id, dst, code, name, work_days, hours_per_day, holidays, is_default, source_id from sch_calendars where version_id = src;
  insert into sch_activities (project_id, version_id, uid, code, source_id, name, wbs_code, wbs_path, activity_type, calendar_id, orig_duration, rem_duration, planned_start, planned_finish, actual_start, actual_finish, pct_complete, constraint_type, constraint_date, budget_cost, owner, sort)
    select a.project_id, dst, a.uid, a.code, a.source_id, a.name, a.wbs_code, a.wbs_path, a.activity_type, (select id from sch_calendars where version_id = dst limit 1), a.orig_duration, a.rem_duration, a.planned_start, a.planned_finish, a.actual_start, a.actual_finish, a.pct_complete, a.constraint_type, a.constraint_date, a.budget_cost, a.owner, a.sort
    from sch_activities a where a.version_id = src;
  insert into sch_relations (project_id, version_id, pred_id, succ_id, rel_type, lag_days)
    select r2.project_id, dst, dp.id, ds.id, r2.rel_type, r2.lag_days
    from sch_relations r2 join sch_activities sp on sp.id = r2.pred_id join sch_activities ss on ss.id = r2.succ_id
    join sch_activities dp on dp.version_id = dst and dp.uid = sp.uid join sch_activities ds on ds.version_id = dst and ds.uid = ss.uid
    where r2.version_id = src;
end $f$;

