alityIndex":0.108},{"uid":"S102","code":"S102","name":"نصب شیرآلات و پایپینگ شیرخانهٔ ۱","correlation":0.04337604106828282,"criticalityIndex":0.08066666666666666},{"uid":"S202","code":"S202","name":"نصب شیرآلات و پایپینگ شیرخانهٔ ۲","correlation":0.041240522290261775,"criticalityIndex":0.07633333333333334},{"uid":"C310","code":"C310","name":"عبور از موانع (جاده، رودخانه، قنات) — بخش ۳","correlation":0.03425712299852751,"criticalityIndex":0},{"uid":"C604","code":"C604","name":"جوشکاری خط لوله — بخش ۶","correlation":0.02328382607272612,"criticalityIndex":0},{"uid":"P3108","code":"P3108","name":"تحویل لوله برای بخش ۸","correlation":0.021233379190625335,"criticalityIndex":0.21033333333333334},{"uid":"P3107","code":"P3107","name":"تحویل لوله برای بخش ۷","correlation":0.01997974939836065,"criticalityIndex":0.036}],"eventHits":[{"id":"e0","title":"تأخیر شیرهای ۴۸ اینچ مسدودکننده","hitRate":0.45366666666666666},{"id":"e1","title":"کمبود لولهٔ ۴۸ اینچ برای جبههٔ شمال","hitRate":0.5133333333333333},{"id":"e2","title":"عدم صدور مجوز آب منطقه‌ای برای گذرهای HDD","hitRate":0.344},{"id":"e3","title":"توقف جوش در مناطق کلاس ۳ (تأیید ضخامت جداره)","hitRate":0.30033333333333334},{"id":"e4","title":"نوسان نرخ یورو در قرارداد تأمین لوله","hitRate":0.6073333333333333}],"warnings":[]}$res$;
  hol date[] := array['2027-02-11','2027-03-21','2027-03-22','2027-03-23','2027-03-24','2027-04-01','2027-04-02']::date[];
  nact int; nrel int; cal uuid; r record; pr record;
begin
  if exists (select 1 from sch_versions where project_id = pid) then raise exception 'already_seeded'; end if;
  perform set_config('sch.rpc', '1', true);

  create temp table s_rows on commit drop as
    select row_number() over () as ord, split_part(l, '|', 1) as code, split_part(l, '|', 2) as name, split_part(l, '|', 3) as wbs, split_part(l, '|', 4) as path,
           split_part(l, '|', 5) as type, split_part(l, '|', 6)::numeric as dur, split_part(l, '|', 7)::numeric as budget, split_part(l, '|', 8) as preds,
           split_part(l, '|', 9)::date as st, split_part(l, '|', 10)::date as fin
    from regexp_split_to_table(spec, E'\n') as l where l <> '';
  create temp table s_uid on commit drop as select code, gen_random_uuid() as uid from s_rows;
  insert into s_uid values ('X4060', gen_random_uuid());
  select count(*) into nact from s_rows;
  select coalesce(sum(cardinality(string_to_array(preds, ';'))), 0) into nrel from s_rows where preds <> '';

  -- versions (drafts first: children can only be written while the version is a draft)
  insert into sch_versions (id, project_id, label, kind, source, file_name, file_hash, data_date, project_start, project_finish, status, parent_version_id, summary, note, created_at) values
    (v0, pid, 'Rev0 — خط مبنا', 'baseline', 'excel', 'KS48-Baseline-Rev0.xlsx', 'demo-rev0', '2026-08-19', '2026-08-19', '2027-05-24', 'draft', null, jsonb_build_object('activities', nact, 'relations', nrel, 'calendars', 1, 'errors', 0, 'warnings', 0), 'دادهٔ نمایشی — برنامهٔ مبنای پروژه', now() - interval '60 days'),
    (v1, pid, 'Rev1 — به‌روزرسانی ۲۶ شهریور ۱۴۰۵', 'update', 'p6_xer', 'KS48-Update-Rev1.xer', 'demo-rev1', '2026-09-17', '2026-08-19', '2027-05-24', 'draft', v0, jsonb_build_object('activities', nact, 'relations', nrel, 'calendars', 1, 'errors', 0, 'warnings', 0), 'دادهٔ نمایشی — به‌روزرسانی ماهانهٔ اول', now() - interval '30 days'),
    (v2, pid, 'Rev2 — به‌روزرسانی ۲۵ مهر ۱۴۰۵', 'update', 'p6_xer', 'KS48-Update-Rev2.xer', 'demo-rev2', '2026-10-17', '2026-08-19', '2027-06-21', 'draft', v0, jsonb_build_object('activities', nact + 1, 'relations', nrel + 2, 'calendars', 1, 'errors', 0, 'warnings', 1), 'دادهٔ نمایشی — شامل دستور تغییر پوشش بخش ۴ و تمدید گذر بخش ۵', now() - interval '1 day'),
    (v3, pid, 'سناریو — جبران تأخیر با کار شیفتی (بخش ۶ تا ۸)', 'scenario', 'copy', '', '', '2026-10-17', '2026-08-19', null, 'draft', v2, jsonb_build_object('activities', nact + 1), 'دادهٔ نمایشی — کاهش ۲۰٪ مدت جوشکاری بخش‌های ۶ تا ۸ با شیفت دوم', now() - interval '2 hours');

  -- Rev0
  insert into sch_calendars (project_id, version_id, code, name, work_days, hours_per_day, holidays, is_default, source_id)
    values (pid, v0, 'CAL-6D', 'تقویم اجرا — شنبه تا پنجشنبه', '{0,1,2,3,4,5}', 8, hol, true, 'CAL-6D') returning id into cal;
  insert into sch_activities (project_id, version_id, uid, code, source_id, name, wbs_code, wbs_path, activity_type, calendar_id, orig_duration, planned_start, planned_finish, budget_cost, sort)
    select pid, v0, u.uid, x.code, x.code, x.name, x.wbs, x.path, x.type, case when x.type = 'summary' then null else cal end, x.dur, x.st, x.fin, x.budget, x.ord::int from s_rows x join s_uid u using (code);
  insert into sch_relations (project_id, version_id, pred_id, succ_id, rel_type, lag_days)
    select pid, v0, ap.id, asu.id, split_part(p, ':', 2), split_part(p, ':', 3)::numeric
    from s_rows x cross join lateral unnest(string_to_array(x.preds, ';')) as p
    join sch_activities asu on asu.version_id = v0 and asu.code = x.code
    join sch_activities ap on ap.version_id = v0 and ap.code = split_part(p, ':', 1)
    where x.preds <> '';

  -- Rev1, Rev2: copies of Rev0 (same activity uids), then the status of each data date
  perform pg_temp.sch_copy(v0, v1);
  for r in select split_part(l, '|', 2) as code, split_part(l, '|', 3) as a, split_part(l, '|', 4) as b, split_part(l, '|', 5) as c, split_part(l, '|', 6) as d
           from regexp_split_to_table(act, E'\n') as l where l like '1|%' loop
    update sch_activities set actual_start = r.a::date, actual_finish = nullif(r.b, '')::date, pct_complete = r.c::numeric, rem_duration = r.d::numeric where version_id = v1 and code = r.code;
  end loop;
  perform pg_temp.sch_copy(v0, v2);
  for r in select split_part(l, '|', 2) as code, split_part(l, '|', 3) as a, split_part(l, '|', 4) as b, split_part(l, '|', 5) as c, split_part(l, '|', 6) as d
           from regexp_split_to_table(act, E'\n') as l where l like '2|%' loop
    update sch_activities set actual_start = r.a::date, actual_finish = nullif(r.b, '')::date, pct_complete = r.c::numeric, rem_duration = r.d::numeric where version_id = v2 and code = r.code;
  end loop;
  for r in select split_part(l, '|', 2) as code, split_part(l, '|', 3) as a from regexp_split_to_table(act, E'\n') as l where l like 'SNET|%' loop
    update sch_activities set constraint_type = 'SNET', constraint_date = r.a::date where version_id = v2 and code = r.code;
  end loop;
  -- Rev2 change order: coating rework in section 4; the section-5 crossing is extended
  update sch_activities set orig_duration = 45 where version_id = v2 and code = 'C510';
  select split_part(l, '|', 3)::date as s, split_part(l, '|', 4)::date as f into pr from regexp_split_to_table(act, E'\n') as l where l like 'XNEW|%';
  insert into sch_activities (project_id, version_id, uid, code, source_id, name, wbs_code, wbs_path, activity_type, calendar_id, orig_duration, planned_start, planned_finish, budget_cost, sort)
    select pid, v2, u.uid, 'X4060', 'X4060', 'اصلاح پوشش معیوب لوله‌ها — بخش ۴ (دستور تغییر)', '4.4', 'ساخت خط لوله > بخش ۴', 'task', (select id from sch_calendars where version_id = v2 limit 1), 6, pr.s, pr.f, 4200000000, 9999
    from s_uid u where u.code = 'X4060';
  insert into sch_relations (project_id, version_id, pred_id, succ_id, rel_type, lag_days)
    select pid, v2, (select id from sch_activities where version_id = v2 and code = 'C405'), (select id from sch_activities where version_id = v2 and code = 'X4060'), 'SS', 2
    union all
    select pid, v2, (select id from sch_activities where version_id = v2 and code = 'X4060'), (select id from sch_activities where version_id = v2 and code = 'C409'), 'FF', 0;
  perform pg_temp.sch_copy(v2, v3);
  -- scenario: shift work on sections 6–8 (second shift shortens welding by 20 %)
  update sch_activities set orig_duration = round(orig_duration * 0.8), rem_duration = case when rem_duration is not null then round(rem_duration * 0.8) end
    where version_id = v3 and code in ('C604', 'C704', 'C804') and actual_finish is null;

  -- lifecycle: approve, baseline, current
  update sch_versions set status = 'approved', is_baseline = true, approved_by = admin_id, approved_at = now() - interval '59 days' where id = v0;
  update sch_versions set status = 'approved', approved_by = admin_id, approved_at = now() - interval '29 days' where id = v1;
  update sch_versions set status = 'approved', is_current = true, approved_by = admin_id, approved_at = now() - interval '12 hours' where id = v2;
  insert into sch_imports (project_id, version_id, file_name, file_hash, format, row_count, ok_count, warn_count, error_count, imported_at) values
    (pid, v0, 'KS48-Baseline-Rev0.xlsx', 'demo-rev0', 'excel', nact, nact, 0, 0, now() - interval '60 days'),
    (pid, v1, 'KS48-Update-Rev1.xer', 'demo-rev1', 'p6_xer', nact, nact, 0, 0, now() - interval '30 days'),
    (pid, v2, 'KS48-Update-Rev2.xer', 'demo-rev2', 'p6_xer', nact + 1, nact, 1, 0, now() - interval '1 day');
  insert into sch_history (project_id, version_id, action, detail, at) values
    (pid, v0, 'import', jsonb_build_object('label', 'Rev0 — خط مبنا'), now() - interval '60 days'),
    (pid, v0, 'approve', jsonb_build_object('label', 'Rev0 — خط مبنا'), now() - interval '59 days'),
    (pid, v0, 'set_baseline', jsonb_build_object('label', 'Rev0 — خط مبنا'), now() - interval '59 days'),
    (pid, v1, 'import', jsonb_build_object('label', 'Rev1 — به‌روزرسانی ۲۶ شهریور ۱۴۰۵'), now() - interval '30 days'),
    (pid, v1, 'approve', jsonb_build_object('label', 'Rev1 — به‌روزرسانی ۲۶ شهریور ۱۴۰۵'), now() - interval '29 days'),
    (pid, v2, 'import', jsonb_build_object('label', 'Rev2 — به‌روزرسانی ۲۵ مهر ۱۴۰۵'), now() - interval '1 day'),
    (pid, v2, 'approve', jsonb_build_object('label', 'Rev2 — به‌روزرسانی ۲۵ مهر ۱۴۰۵'), now() - interval '12 hours'),
    (pid, v2, 'set_current', jsonb_build_object('label', 'Rev2 — به‌روزرسانی ۲۵ مهر ۱۴۰۵'), now() - interval '12 hours'),
    (pid, v3, 'copy', jsonb_build_object('label', 'سناریو — جبران تأخیر با کار شیفتی (بخش ۶ تا ۸)'), now() - interval '2 hours');

  -- links to the other modules (by stable activity uid)
  create temp table s_link (code text, ttype text, tid uuid, kind text) on commit drop;
  -- execution activities (price-book chapters → the schedule activity that performs them; spread over sections)
  insert into s_link
    select case
      when ch like 'فصل اول - عملیات ریسه%' then 'C' || (rn % 8 + 1) || '02'
      when ch like 'فصل دوم - آماده سازی%' then 'C' || (rn % 8 + 1) || '04'
      when ch like 'فصل سوم - آزمایش%' then 'C' || (rn % 8 + 1) || '05'
      when ch like 'فصل چهارم - عایقکاری%' then 'C' || (rn % 8 + 1) || '06'
      when ch like 'فصل سیزدهم - عملیات خاکی%' then 'C' || (rn % 8 + 1) || '07'
      when ch like 'فصل ششم - عبور%' then 'C' || (rn % 8 + 1) || '10'
      when ch like 'فصل هفتم - آزمایش%' then 'C' || (rn % 8 + 1) || '11'
      when ch like 'فصل پنجم - نصب شیر%' then 'S' || (rn % 4 + 1) || '02'
      when ch like '%کارهای برق%' then 'S' || (rn % 4 + 1) || '03'
      when ch like 'فصل هشتم - حفاظت کاتدیک%' then case when rn % 2 = 0 then 'CP6020' else 'CP6030' end
      when ch like 'فصل سوم -عملیات خاکی با ماشین%' then 'C' || (rn % 8 + 1) || '01'
      when ch ~ '^[0-9]+- ' then 'S' || (rn % 4 + 1) || '01'
    end, 'exec_activity', id, 'start'
    from (select id, chapter as ch, (row_number() over (partition by chapter order by sort, id) - 1)::int as rn from ex_activities where project_id = pid and active) e;
  -- engineering documents (the document a construction activity needs; needed by that activity's baseline start)
  insert into s_link
    select case
      when discipline = 'Pipeline' and category in ('PPF', 'LAY', 'DWG') then 'C' || (rn % 8 + 1) || '01'
      when discipline = 'Pipeline' and category in ('TYP', '') then 'C' || (rn % 8 + 1) || '10'
      when discipline = 'Pipeline' and category in ('CAL', 'SPC', 'DSH') then 'C' || (rn % 8 + 1) || '03'
      when discipline = 'Welding' then 'C' || (rn % 2 + 1) || '04'
      when discipline = 'Coating' then 'C' || (rn % 2 + 1) || '06'
      when discipline = 'Geotechnical' then 'C' || (rn % 3 * 2 + 3) || '10'
      when discipline = 'Civil' and category in ('DWG', 'TYP', 'CAL', '') then 'S' || (rn % 4 + 1) || '01'
      when discipline = 'Piping' and category in ('DWG', 'LIS', 'STD') then 'S' || (rn % 4 + 1) || '02'
      when discipline = 'Mechanical' and category in ('', 'DSH', 'SPC') then 'S' || (rn % 4 + 1) || '02'
      when discipline in ('Electrical', 'Instrument') and category in ('DIA', 'LAY', 'SCH', 'TYP', '', 'CAL', 'DWG') then 'S' || (rn % 4 + 1) || '03'
      when discipline = 'Cathodic Protection' and category in ('', 'CAL', 'DSH', 'DWG', 'LAY', 'SPC') then 'CP6010'
    end, 'eng_doc', id, 'start'
    from (select id, discipline, category, (row_number() over (partition by discipline order by doc_no, id) - 1)::int as rn from ex_eng_docs where project_id = pid) d;
  -- supply packages: valves (PK-02) for the valve-station piping, welding consumables (PK-04) for the later welding sections
  insert into s_link select 'S' || g || '02', 'mtl_package', p.id, 'start' from mtl_packages p, generate_series(1, 4) g where p.master_project_id = pid and p.code = 'PK-02';
  insert into s_link select 'C' || g || '04', 'mtl_package', p.id, 'start' from mtl_packages p, generate_series(4, 8) g where p.master_project_id = pid and p.code = 'PK-04';
  -- risks and issues of the project
  insert into s_link
    select x.code, 'risk', x.rid::uuid, 'start' from (values
      ('P3040', '7cec7f98-b3b9-4587-bbe1-d7cee69a187a'), ('S102', '7cec7f98-b3b9-4587-bbe1-d7cee69a187a'), ('S202', '7cec7f98-b3b9-4587-bbe1-d7cee69a187a'), ('S302', '7cec7f98-b3b9-4587-bbe1-d7cee69a187a'), ('S402', '7cec7f98-b3b9-4587-bbe1-d7cee69a187a'),
      ('P3010', 'e2572e77-0622-417f-be4b-c52e7fbb35db'),
      ('C404', '2308e9bd-ce39-48c7-81bc-77899acff62b'), ('C504', '2308e9bd-ce39-48c7-81bc-77899acff62b'), ('C604', '2308e9bd-ce39-48c7-81bc-77899acff62b'),
      ('C310', 'bbf380c3-03e3-4722-93ad-23d2f5cb557f'), ('C510', 'bbf380c3-03e3-4722-93ad-23d2f5cb557f'), ('C710', 'bbf380c3-03e3-4722-93ad-23d2f5cb557f')) as x(code, rid)
    where exists (select 1 from rm_risks where id = x.rid::uuid);
  insert into s_link
    select x.code, 'issue', x.iid::uuid, 'start' from (values
      ('P3106', 'e508e7d7-1e29-44b0-b8f2-789c84077c0c'), ('P3107', 'e508e7d7-1e29-44b0-b8f2-789c84077c0c'), ('P3108', 'e508e7d7-1e29-44b0-b8f2-789c84077c0c'), ('C602', 'e508e7d7-1e29-44b0-b8f2-789c84077c0c'), ('C702', 'e508e7d7-1e29-44b0-b8f2-789c84077c0c'), ('C802', 'e508e7d7-1e29-44b0-b8f2-789c84077c0c'),
      ('P3040', 'f5dac5c6-fe17-432e-bef3-ef2dbe727011'), ('S102', 'f5dac5c6-fe17-432e-bef3-ef2dbe727011'), ('S202', 'f5dac5c6-fe17-432e-bef3-ef2dbe727011'),
      ('C106', 'd6bf5fec-0a76-49fc-a5db-be396f3cb3a2'), ('C206', 'd6bf5fec-0a76-49fc-a5db-be396f3cb3a2'), ('C306', 'd6bf5fec-0a76-49fc-a5db-be396f3cb3a2'), ('C406', 'd6bf5fec-0a76-49fc-a5db-be396f3cb3a2'),
      ('S101', 'f1981719-8c20-46b6-8bf9-ff8f55f84de5'), ('S201', 'f1981719-8c20-46b6-8bf9-ff8f55f84de5'), ('S301', 'f1981719-8c20-46b6-8bf9-ff8f55f84de5'), ('S401', 'f1981719-8c20-46b6-8bf9-ff8f55f84de5'),
      ('C310', 'a5bb3adc-9475-45b5-9a6d-cce9f022e48f'), ('C510', 'a5bb3adc-9475-45b5-9a6d-cce9f022e48f'), ('C710', 'a5bb3adc-9475-45b5-9a6d-cce9f022e48f'), ('E2010', 'a5bb3adc-9475-45b5-9a6d-cce9f022e48f')) as x(code, iid)
    where exists (select 1 from im_issues where id = x.iid::uuid);
  insert into sch_links (project_id, activity_uid, target_type, target_id, need_kind, need_date)
    select pid, u.uid, l.ttype, l.tid, l.kind, case when l.ttype in ('eng_doc', 'mtl_package') then x.st end
    from s_link l join s_uid u on u.code = l.code join s_rows x on x.code = l.code where l.code is not null
    on conflict do nothing;

  -- quantitative analysis inputs and one saved run (Rev2)
  insert into sch_duration_risk (project_id, activity_uid, min_dur, likely_dur, max_dur, note)
    select pid, u.uid, split_part(d, ':', 2)::numeric, split_part(d, ':', 3)::numeric, split_part(d, ':', 4)::numeric, 'دادهٔ نمایشی'
    from unnest(string_to_array(drs, ',')) as d join s_uid u on u.code = split_part(d, ':', 1);
  insert into sch_risk_events (project_id, title, risk_id, probability, days_min, days_likely, days_max, cost_min, cost_likely, cost_max, activity_uids, active, note)
    select pid, e ->> 0, nullif(e ->> 9, '')::uuid, (e ->> 1)::numeric, (e ->> 2)::numeric, (e ->> 3)::numeric, (e ->> 4)::numeric, (e ->> 5)::numeric, (e ->> 6)::numeric, (e ->> 7)::numeric,
           array(select u.uid from jsonb_array_elements_text(e -> 8) c join s_uid u on u.code = c), true, 'دادهٔ نمایشی'
    from jsonb_array_elements(evs) e;
  insert into sch_simulations (project_id, version_id, seed, iterations, params, result, created_at)
    values (pid, v2, 20261017, 3000, jsonb_build_object('durationRisks', (select count(*) from sch_duration_risk where project_id = pid), 'events', (select count(*) from sch_risk_events where project_id = pid), 'dataDate', '2026-10-17'), res, now() - interval '10 hours');
end
$seed$;
